function toggleMobileSearch() {
  const searchBar = document.getElementById('mobile-search-bar');

  if (searchBar) {
    const isOpen = searchBar.getAttribute('data-open') === 'true';

    if (!isOpen) {
      searchBar.style.maxHeight = '100px';
      searchBar.style.opacity = '1';
      searchBar.setAttribute('data-open', 'true');

      const searchInput = searchBar.querySelector('input[type="search"]');
      if (searchInput) {
        setTimeout(() => searchInput.focus(), 300);
      }
    } else {
      searchBar.style.maxHeight = '0';
      searchBar.style.opacity = '0';
      searchBar.setAttribute('data-open', 'false');
    }
  }
}

// Ensure DOM is loaded before attaching event listeners
document.addEventListener('DOMContentLoaded', function() {
  const toggleButton = document.getElementById('mobile-search-toggle');
  const searchBar = document.getElementById('mobile-search-bar');

  if (searchBar) {
    searchBar.setAttribute('data-open', 'false');
  }
});

